#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <Adafruit_I2CDevice.h>

// XIAO ESP32S3の物理ピン定義
#define TFT_RST   2   // D1
#define TFT_DC    3   // D2
#define TFT_CS    4   // D3
#define TFT_SCLK  8   // D8
#define TFT_MOSI 10   // D10
#define TFT_MISO -1   // 液晶からはデータを受け取らないため未使用

// ハードウェアSPIを使用する設定
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  Serial.begin(115200);

  // 【重要】ESP32S3のSPIバスを定義したピンで強制的に初期化
  // クロック、MISO、MOSI、CSの順
  SPI.begin(TFT_SCLK, TFT_MISO, TFT_MOSI, TFT_CS);

  // 液晶側の通信初期化
  tft.initR(INITR_BLACKTAB);

  // 画面の初期化と描画
  tft.setRotation(1);
  tft.fillScreen(ST7735_BLACK);

  // テキスト表示
  tft.setCursor(10, 20);
  tft.setTextColor(ST7735_WHITE);
  tft.setTextSize(2);
  tft.println("XIAO ESP32S3");

  tft.setCursor(10, 50);
  tft.setTextColor(ST7735_GREEN);
  tft.println("SPI FIXED");

  tft.drawRect(5, 5, 150, 118, ST7735_BLUE);
}

void loop() {
  tft.setCursor(10, 80);
  tft.setTextColor(ST7735_RED, ST7735_BLACK);
  tft.print("Sending...  ");
  delay(500);

  tft.setCursor(10, 80);
  tft.setTextColor(ST7735_YELLOW, ST7735_BLACK);
  tft.print("Sending... *");
  delay(500);
}
